import java.util.*;

class Solution {
    public int numSquares(int n) {
        Deque<Integer> queue = new ArrayDeque<>();
        queue.add(n);
        int steps = 0;

        while (!queue.isEmpty()) {
            int size = queue.size();
            for (int i = 0; i < size; i++) {
                int cur = queue.poll();
                if (cur == 0) return steps;
                for (int k = 1; k * k <= cur; k++) {
                    queue.add(cur - k * k);
                }
            }
            steps++;
        }
        return steps;
    }
}

class Solution {
    public int numSquares(int n) {
        int[] dp = new int[n + 1];
        for (int i = 1; i <= n; i++) dp[i] = n + 1;
        dp[0] = 0;

        for (int i = 1; i <= n; i++) {
            for (int k = 1; k * k <= i; k++) {
                dp[i] = Math.min(dp[i], dp[i - k * k] + 1);
            }
        }
        return dp[n];
    }
}

class Solution {
    public int numSquares(int n) {
        if (isSquare(n)) return 1;

        int m = n;
        while (m % 4 == 0) m /= 4;
        if (m % 8 == 7) return 4;

        for (int a = 1; a * a <= n; a++) {
            if (isSquare(n - a * a)) return 2;
        }
        return 3;
    }

    private boolean isSquare(int x) {
        int s = (int) Math.sqrt(x);
        return (long) s * s == x;
    }
}
